class TransferLedger:
    def __init__(self, balances):
        self.balances = dict(balances)
        self._seen = set()

    def transfer(self, txid, source, target, amount):
        if txid in self._seen:
            return True
        self.balances[source] -= amount
        self.balances[target] += amount
        self._seen.add(txid)
        return True

class RevisionCache:
    def __init__(self):
        self.source = {}
        self.revisions = {}
        self.cache = {}

    def read(self, key):
        if key in self.cache:
            return self.cache[key]
        value = self.source.get(key)
        self.cache[key] = value
        return value

    def put(self, key, value):
        self.source[key] = value
        self.revisions[key] = self.revisions.get(key, 0) + 1

    def delete(self, key):
        self.source.pop(key, None)

class SnapshotMap:
    def __init__(self, initial=None):
        self.data = dict(initial or {})
        self.version = 0

    def begin(self):
        return {"version": self.version, "values": self.data}

    def commit(self, snapshot, writes):
        if snapshot["version"] != self.version:
            return False
        for key, value in writes.items():
            if value is None:
                self.data.pop(key, None)
            else:
                self.data[key] = value
        self.version += 1
        return True

class ReservationBook:
    def __init__(self):
        self.active = {}
        self.next_token = 0

    def reserve(self, keys, owner, now, ttl):
        tokens = {}
        for key in keys:
            current = self.active.get(key)
            if current and current['expires_at'] > now and current['owner'] != owner:
                return None
            self.next_token += 1
            token = self.next_token
            self.active[key] = {'owner': owner, 'token': token, 'expires_at': now + ttl}
            tokens[key] = token
        return tokens

    def release(self, key, owner, token):
        current = self.active.get(key)
        if not current or current['owner'] != owner or current['token'] != token:
            return False
        del self.active[key]
        return True
